from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
rows=[
('余烬中的主唱','坚持3波，救回凑企鹅','第四章落幕时，凑企鹅走进雾中，原想独自偿还过错。它却被地狱的锁链拖入熔炉。音乐小队循着断续的歌声赶来：这一次，没有人该独自谢幕。','三色奶娃第一次出现：墨绿铁壁减伤，紫色幽咒禁锢，红色狂焰强化攻击。每波清完才会刷新下一波。',[
('penguin_full','afraid','我以为只要自己消失，大家就会好过一点。可锁链把我拖到这里时，我才发现……我还是想听见你们的声音。'),('soyo','dialogue','认错不是离开。回来把没唱完的歌唱完吧。'),('mutsumi','victory','音乐小队重新团圆。共鸣强化了我们的生命、攻击与防御。凑企鹅会自主掩护，不占用玩家操控席位。')]),
('葱绿的回声','坚持5波，解救初音未来','一支大葱在牢笼里敲出节拍。初音用歌声牵住锁链，护住被押送的人。无色的袋鼠狗、肥袋鼠狗、奶娃狗、奶娃鼠正在围拢。','袋鼠狗弹射突进；肥袋鼠狗落地震荡；奶娃狗扑咬；奶娃鼠远程散射。幼体、小型、中级、完全体逐级增强。',[
('miku','dialogue','谢谢你们。这里的锁链会追逐声音，那就让我把声音变成困住它们的藤蔓。'),('miku','victory','缚魂大葱已解锁：音波禁锢并持续削弱敌人。初音作为向导留下，千本樱响起，为继续向下的人照亮路。')]),
('红白巫女的消息','坚持8波，救出博丽灵梦','红白衣角落在祭坛旁。博丽灵梦守着一道破损结界，她看见了四个赌气离家的身影：菲比、糯糯、Doro、咕嘎，被分别送往更深的牢狱。','彩色敌人的强化现在覆盖四个族群。灵梦赤月镰刀横扫身边一圈，能斩杀中级及以下奶娃；F释放三倍伤害领域。',[
('reimu','dialogue','她们不是不在乎你。恰好相反，她们太想证明自己没有被替代，才跟着假的路标走进这里。'),('ikun','afraid','那么第四章的离开，不是永别……我们还能把她们带回来。'),('reimu','proud','我会同行。不要追逐牢门里的回声，看清真正站在你身边的人。赤月大镰刀已经准备好了。')]),
('不再返场的巡演','坚持10波，护送音乐团离开','回到舞台的路即将坍塌。音乐团决定护送沿途囚徒离开地狱，只有一支队伍能随你继续下潜。初音和灵梦留下带路，原音乐小队必须走向自己的巡演。','本关敌人密集，利用禁锢与范围攻击；留出补给窗口。完成后睦子米、soyo、爱音与自主凑企鹅永久离开当前旅程。',[
('anon','dialogue','这次告别不是生气，也不是等你来哄。我们找回了主唱，也找到了该去的地方。外面还有人等着听我们的歌。'),('penguin_full','dialogue','我会跟她们走，把做错的事一件件补回来。你去找你的朋友。'),('soyo','victory','谢谢你陪我们走到团圆。别为留住我们而停下。音乐小队离开本次旅程；只有重新游玩第四章或重置存档，才能再次与她们并肩。')]),
('断线后的来电','坚持5波，击败熔炉狱卒','菲比的电话从深处传来。她先发脾气，随后带着哭腔说出四人的下落。最后一波，熔炉狱卒将封住通往橘色牢笼的桥。','狱卒只在最后一波登场。红圈陨落会留火场，不要停留；先处理召唤物，保留禁锢打断追击。',[
('ikun','proud','第一道狱锁断了。电话里的声音不是诱饵，菲比真的在等我们。'),('reimu','dialogue','下一座牢笼关着Doro。带上药品，这条路已经不能靠勇气硬闯。')]),
('橘色牢笼','坚持7波，击败缚魂灯守，救出Doro','灯守把Doro的橘子收在玻璃灯里，照着一条永远走不到出口的路。她仍在敲牢门，给朋友留下能听见的节拍。','第二狱主的幽咒控制很危险。绕开红圈与散射，清完最后一波和首领才能解锁Doro。',[
('doro','afraid','Doro……欧润。'),('ikun','dialogue','知道了。你一直在等大家，没有放弃。'),('doro','victory','Doro！她抱着橘子跳出牢笼，指向断翼回廊。Doro重新加入，可从背包切换。')]),
('折翼的回声','坚持7波，击败断翼刽子手，救出咕嘎','咕嘎用翅膀护住锁链留下的伤口，仍不肯丢掉朋友送的石头。刽子手把它的求救声当成战鼓。','第三狱主快速压近。侧向闪避弹射与飞扑，优先清除鼠类射手，再集中处理首领。',[
('gugu','angry','咕嘎！这块石头不是拿来砸朋友的。'),('gugu','victory','锁链落下，咕嘎把石头抱回怀里。它要把被夺走的路一点点砸开。咕嘎重新加入，保留原石与继承技能。')]),
('静夜留下的路标','坚持10波，击败静默典狱长，救出糯糯','糯糯把微弱的灯光藏在袖口，每隔一段时间就照向更深的塔。她记得菲比被带走的方向，却始终等不到回答。','第四狱主与高阶守卫交替施压。活着比追伤害更重要，最后一波再使用破甲战歌。',[
('nuonuo','afraid','我不怪她。是我们一起决定出走的，不该让她一个人承担。'),('nuonuo','dialogue','菲比被带进了最深处。但下一座祭坛会模仿她的声音，别立刻冲进去。我们一起去找她。糯糯重新加入。')]),
('时空胶囊的交易','清除10波与织谎者，决定奥摩的请求','祭坛里传来菲比的笑声，门后却空无一人。最终狱主留下的化身堵住退路。你必须先击败织谎者，才能知道是谁在另一头呼叫。','这不是菲比所在的牢笼。战后会获得时空胶囊，选择交给奥摩可获得下一关援助；留下则保留未来时空探索的钥匙。决定会写入存档。',[
('omo','dialogue','你看到的我，不属于这个时代。我能切开最后一道狱锁，帮你把菲比带回来。但我需要时空胶囊返回自己的坐标。'),('reimu','dialogue','胶囊只能稳定一次航路。给他，他会兑现援助后离开；留下，你将来能去他的时代寻找先进装备与伙伴。那个时代的入口还没有开启。'),('omo','proud','我不强迫你。把胶囊给我，我下一关为你清路；你留下，我们便各自面对眼前的路。')]),
('把四个名字带回家','清除12波与地狱终焉，救出菲比','最后一座牢笼在终焉祭坛后。交出胶囊，奥摩将以旋转攻击横扫守卫；保留胶囊，则由你与伙伴一起面对十二波和最终狱主。','最终首领只在最后一波登场。救出菲比后，四小只全部存活时触发友谊之力；任一倒下立即失效，复活后恢复。',[
('phoebe','angry','你怎么现在才来……不许说我哭过，也不许把这件事写进你那个手册里。'),('phoebe','afraid','我以为你有了新朋友，就不再需要我们了。后来每次听见脚步声，我都在想，会不会是你。'),('ikun','dialogue','新的朋友不会替代你们。下次生气可以说，别再让一扇假门把我们分开。'),('phoebe','victory','那……这次算和好。看好了，我只表演一次！以后要一起出发，也要一起回来。'),('nuonuo','victory','四个名字终于重新连在一起。只要菲比、糯糯、Doro与咕嘎都活着，友谊之力就会加强大家；对完全体奶娃，每次命中至少削去70%最大生命。')])]
data={}
for i,(title,goal,intro,hint,pages) in enumerate(rows,38):
 ending=[{'speaker':s,'emotion':e,'text':t} for s,e,t in pages]
 if i==46:ending[-1]['choices']=[{'id':'give','text':'交出胶囊，换取下一关援助'},{'id':'keep','text':'留下胶囊，将来探索他的时空'}]
 if i==47:ending[1]['choices']=[{'id':'hug','text':'抱住她：我们一直都需要你'},{'id':'tease','text':'先回家，再慢慢听你发脾气'}]
 choices=[{'id':'act','text':'我准备好了，开始行动','speaker':'ikun','emotion':'proud','reply':'记住目标，留意红色蓄力，活着把朋友带回来。'},{'id':'plan','text':'请说明敌人和救援要点','speaker':'ikun','emotion':'dialogue','reply':hint}]
 data[str(i)]={'title':title,'goal':goal,'npc':'渡火人·烬灯','task':goal+'。'+hint,'clue':hint,'briefing':intro,'intro':{'speaker':'ikun','emotion':'battle','text':intro,'choices':choices},'outro':{'speaker':ending[-1]['speaker'],'emotion':'victory','text':ending[-1]['text'],'choices':[{'id':'continue','text':'继续','speaker':'ikun','emotion':'proud','reply':'新的路已经开启。'}]},'ending':ending}
(R/'Story/Data/chapter5.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
(R/'Docs/第五章剧情.md').write_text('# 第五章：余烬中的约定\n\n'+'\n\n'.join('## 5-%d %s\n\n任务：%s\n\n%s\n\n%s\n\n%s'%(i+1,r[0],r[1],r[2],r[3],'\n\n'.join(s+'（'+e+'）：'+t for s,e,t in r[4])) for i,r in enumerate(rows)),encoding='utf-8')
